<script setup lang="ts">
import{onMounted,reactive,ref}from'vue';import { actualizarUsuario, asignarEmpresa, asignarModulo, crearUsuario, listarUsuarios, quitarEmpresa, quitarModulo, verAccesos } from '../services/usuarios'
import type { Accesos, Options, Payload, Usuario } from '../interfaces/usuarios.interface'
const rows=ref<Usuario[]>([]),options=ref<Options>({empresas:[],oficinas:[],modulos:[],roles:[],tipos_modulo:[]}),criterion=ref(''),company=ref(0),page=ref(1),last=ref(1),total=ref(0),superAdmin=ref(false),loading=ref(false),saving=ref(false),modal=ref(false),editing=ref<Usuario|null>(null),accessUser=ref<Usuario|null>(null),access=ref<Accesos|null>(null),error=ref(''),success=ref(''),moduleId=ref(0),moduleType=ref('usuario'),companyId=ref(0);const empty=():Payload=>({username:'',password:'',dni:'',nombre:'',apellido_paterno:'',apellido_materno:'',correo:'',fecha_nacimiento:'',sexo:'M',tipo_rol:'administrativo',oficina_id:0,activo:true,administrador:false,super_administrador:false,multi_empresa:false}),form=reactive<Payload>(empty());async function load(p=1){page.value=p;loading.value=true;try{const r=await listarUsuarios(criterion.value,company.value,p);rows.value=r.data;total.value=r.total;last.value=r.last_page;options.value=r.options;superAdmin.value=r.es_super_administrador}catch(e){error.value=msg(e)}finally{loading.value=false}}function open(x?:Usuario){editing.value=x||null;Object.assign(form,x?{username:x.username,password:'',dni:x.dni,nombre:x.nombre_completo,apellido_paterno:'',apellido_materno:'',correo:x.correo||'',fecha_nacimiento:x.fecha_nacimiento||'',sexo:x.sexo||'M',tipo_rol:x.tipo_rol,oficina_id:x.oficina_id||0,activo:x.activo,administrador:x.administrador,super_administrador:x.super_administrador,multi_empresa:x.multi_empresa}:empty());modal.value=true;error.value=''}async function save(){if(!/^\d{8}$/.test(form.dni)||!form.username.trim()||!form.nombre.trim()||!form.oficina_id){error.value='Complete usuario, DNI de 8 dígitos, nombre y oficina.';return}if(!editing.value&&(!form.password||form.password.length<8)){error.value='La contraseña inicial debe tener al menos 8 caracteres.';return}saving.value=true;try{editing.value?await actualizarUsuario(editing.value.id,{...form}):await crearUsuario({...form});success.value=editing.value?'Usuario actualizado correctamente.':'Usuario creado correctamente.';modal.value=false;await load(editing.value?page.value:1)}catch(e){error.value=msg(e)}finally{saving.value=false}}async function openAccess(x:Usuario){accessUser.value=x;moduleId.value=companyId.value=0;try{access.value=await verAccesos(x.id)}catch(e){error.value=msg(e)}}async function addModule(){if(!accessUser.value||!moduleId.value)return;await asignarModulo(accessUser.value.id,moduleId.value,moduleType.value);await openAccess(accessUser.value)}async function removeModule(id:number){if(accessUser.value&&confirm('¿Quitar este módulo?')){await quitarModulo(accessUser.value.id,id);await openAccess(accessUser.value)}}async function addCompany(){if(!accessUser.value||!companyId.value)return;await asignarEmpresa(accessUser.value.id,companyId.value);await openAccess(accessUser.value)}async function removeCompany(id:number){if(accessUser.value&&confirm('¿Quitar acceso a esta empresa?')){await quitarEmpresa(accessUser.value.id,id);await openAccess(accessUser.value)}}function msg(e:unknown){return e instanceof Error?e.message:'No se pudo completar la operación.'}onMounted(()=>load())
</script>
<template><div class="page"><nav><RouterLink to="/inicio">Inicio</RouterLink> / Sistema / Usuarios</nav><header class="hero"><div class="mark">US</div><div><small>ADMINISTRACIÓN GENERAL</small><h1>Gestión de usuarios</h1><p>Cuentas, roles, oficinas, módulos y acceso multiempresa.</p></div><strong>{{total}} usuarios</strong><button @click="open()">+ Nuevo usuario</button></header><p v-if="success" class="flash good">✓ {{success}}</p><p v-if="error" class="flash bad">{{error}}</p><section class="filters"><label>Buscar usuario<input v-model.trim="criterion" placeholder="Nombre de usuario" @keyup.enter="load()"></label><label v-if="superAdmin">Empresa<select v-model.number="company"><option :value="0">Todas</option><option v-for="x in options.empresas" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label><button @click="load()">Buscar</button></section><div v-if="loading" class="empty">Cargando usuarios…</div><section v-else class="table"><header><span>Usuario</span><span>Empresa / oficina</span><span>Rol</span><span>Accesos</span><span>Estado</span><span>Acciones</span></header><article v-for="x in rows" :key="x.id"><div><b>{{x.nombre_completo}}</b><small>{{x.username}} · DNI {{x.dni}}</small></div><div><b>{{x.empresa}}</b><small>{{x.oficina||'Sin oficina'}}</small></div><div><b>{{x.tipo_rol}}</b><small>{{x.super_administrador?'Superadministrador':x.administrador?'Administrador':'Usuario'}}</small></div><div><b>{{x.modulos_count}} módulos</b><small>{{x.empresas_count}} empresas</small></div><span :class="x.activo?'active':'inactive'">{{x.activo?'Activo':'Inactivo'}}</span><div class="actions"><button @click="open(x)">Editar</button><button @click="openAccess(x)">Accesos</button></div></article></section><footer v-if="last>1" class="pages"><button :disabled="page<=1" @click="load(page-1)">Anterior</button><span>{{page}} / {{last}}</span><button :disabled="page>=last" @click="load(page+1)">Siguiente</button></footer>
<div v-if="modal" class="backdrop" @mousedown.self="modal=false"><form class="modal" @submit.prevent="save"><header><div><small>{{editing?'EDITAR CUENTA':'NUEVA CUENTA'}}</small><h2>{{editing?editing.nombre_completo:'Registrar usuario'}}</h2></div><button type="button" @click="modal=false">×</button></header><div class="grid"><label>Usuario *<input v-model.trim="form.username"></label><label>{{editing?'Nueva contraseña':'Contraseña inicial *'}}<input v-model="form.password" type="password"></label><label>DNI *<input v-model.trim="form.dni" maxlength="8"></label><label>Nombre completo *<input v-model.trim="form.nombre"></label><label>Correo<input v-model.trim="form.correo" type="email"></label><label>Fecha de nacimiento<input v-model="form.fecha_nacimiento" type="date"></label><label>Sexo<select v-model="form.sexo"><option value="M">Masculino</option><option value="F">Femenino</option></select></label><label>Tipo de rol<select v-model="form.tipo_rol"><option value="administrativo">Administrativo</option><option value="operativo">Operativo</option></select></label><label class="wide">Oficina *<select v-model.number="form.oficina_id"><option :value="0">Seleccione</option><option v-for="x in options.oficinas" :key="x.id" :value="x.id">{{x.nombre}}</option></select></label></div><div class="checks"><label><input v-model="form.activo" type="checkbox"> Activo</label><label><input v-model="form.administrador" type="checkbox"> Administrador</label><label><input v-model="form.multi_empresa" type="checkbox"> Multiempresa</label><label v-if="superAdmin"><input v-model="form.super_administrador" type="checkbox"> Superadministrador</label></div><footer><button type="button" class="clear" @click="modal=false">Cancelar</button><button :disabled="saving">{{saving?'Guardando…':'Guardar usuario'}}</button></footer></form></div>
<div v-if="accessUser&&access" class="backdrop" @mousedown.self="accessUser=null"><section class="modal access"><header><div><small>PERMISOS Y ACCESOS</small><h2>{{accessUser.nombre_completo}}</h2></div><button @click="accessUser=null">×</button></header><h3>Módulos asignados</h3><div class="adder"><select v-model.number="moduleId"><option :value="0">Seleccione módulo</option><option v-for="x in access.disponibles.modulos" :key="x.id" :value="x.id">{{x.nombre}}</option></select><select v-model="moduleType"><option v-for="x in access.disponibles.tipos_modulo" :key="x.id" :value="x.nombre">{{x.nombre}}</option></select><button @click="addModule">Asignar</button></div><div class="list"><div v-for="x in access.modulos" :key="x.id"><b>{{x.nombre}}</b><span>{{x.tipo}}</span><button @click="removeModule(x.id)">Quitar</button></div></div><h3>Empresas asignadas</h3><div class="adder"><select v-model.number="companyId"><option :value="0">Seleccione empresa</option><option v-for="x in access.disponibles.empresas" :key="x.id" :value="x.id">{{x.nombre}}</option></select><button @click="addCompany">Asignar</button></div><div class="list"><div v-for="x in access.empresas" :key="x.id"><b>{{x.nombre}}</b><button @click="removeCompany(x.id)">Quitar</button></div></div></section></div></div></template>
<style scoped>
.page{--a:#334a61;color:#35444c}nav{margin-bottom:16px;color:#96a0a5;font-size:.7rem}nav a{color:var(--a)}.hero{padding:22px 25px;display:flex;align-items:center;gap:15px;border-left:5px solid var(--a);border-radius:13px;background:#fff}.mark{width:52px;height:52px;display:grid;place-items:center;border-radius:11px;color:#fff;background:var(--a);font-weight:800}.hero small,.modal small{color:var(--a);font-size:.52rem;font-weight:700}.hero h1{margin:2px 0;font-size:1.28rem}.hero p{margin:0;color:#7c898f;font-size:.62rem}.hero strong{margin-left:auto;font-size:.5rem}.hero button,.filters button,.pages button,.modal footer button,.adder button{padding:8px 10px;border:0;border-radius:5px;color:#fff;background:var(--a);font-size:.47rem}.flash{padding:10px;font-size:.6rem}.good{color:#267359;background:#eaf8f1}.bad{color:#a13e43;background:#fff0f0}.filters{margin-top:12px;padding:12px;display:flex;align-items:end;gap:8px;background:#fff}.filters label{flex:1;font-size:.47rem}input,select{width:100%;padding:8px;border:1px solid #d7e0e3;border-radius:5px;font:inherit;font-size:.52rem}.table{margin-top:12px;background:#fff}.table>header,.table>article{padding:9px 12px;display:grid;grid-template-columns:1.5fr 1.2fr 1fr .7fr .55fr .8fr;align-items:center;gap:8px;border-bottom:1px solid #e9edee}.table>header{color:#849096;background:#f4f6f7;font-size:.42rem}.table article{font-size:.47rem}.table article b,.table article small{display:block}.table small{color:#89949a;font-size:.4rem}.active,.inactive{padding:4px;border-radius:9px;text-align:center;font-size:.4rem}.active{color:#267359;background:#e7f6ef}.inactive{color:#a13e43;background:#fbeaea}.actions{display:flex;gap:4px}.actions button,.list button{border:0;color:var(--a);background:none;font-size:.43rem}.empty{padding:45px;text-align:center;background:#fff;font-size:.58rem}.pages{display:flex;justify-content:center;gap:8px;font-size:.48rem}.backdrop{position:fixed;z-index:100;inset:0;padding:16px;display:grid;place-items:center;background:#14283888}.modal{width:min(100%,720px);max-height:94vh;overflow:auto;padding:20px;border-radius:12px;background:#fff}.modal>header{display:flex}.modal h2{margin:2px 0;font-size:.85rem}.modal>header>button{margin-left:auto;border:0;background:none;font-size:1.4rem}.grid{margin-top:12px;display:grid;grid-template-columns:1fr 1fr;gap:8px}.grid label{font-size:.47rem}.wide{grid-column:span 2}.checks{margin-top:10px;display:flex;gap:15px;font-size:.47rem}.checks input{width:auto}.modal footer{margin-top:14px;display:flex;justify-content:flex-end}.clear{color:#64737a!important;background:#edf1f2!important}.access{width:min(100%,800px)}.access h3{margin:15px 0 6px;font-size:.6rem}.adder{display:flex;gap:5px}.adder select:first-child{flex:2}.list{margin-top:6px;border:1px solid #e3e8ea}.list div{padding:7px;display:grid;grid-template-columns:1fr .6fr auto;border-bottom:1px solid #e8ecee;font-size:.47rem}@media(max-width:850px){.table>header{display:none}.table>article{grid-template-columns:1fr 1fr}}@media(max-width:540px){.hero{flex-wrap:wrap}.hero strong{margin-left:0}.filters,.adder{align-items:stretch;flex-direction:column}.grid,.table>article{grid-template-columns:1fr}.wide{grid-column:auto}.checks{flex-direction:column}}
